import {parseCSV,parseXLSX,scenariosFromRows,csv} from './imports.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],root=$('#root'),modal=$('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pref=(k,v)=>{try{if(v!==undefined)localStorage.setItem(k,v);return localStorage.getItem(k);}catch{return null;}};
let language=pref('qs-language')||'tr',theme=pref('qacrew-theme')||'dark',user=null,state=null,config={},members=[],projectId='',version='',tab='dashboard',subtab='library',activeRun='',runFilter='all',bugFilter='all',docQuery='',docSort='date',docType='all',draft=null,busy=false;
const t=(tr,en)=>language==='en'?en:tr;
const names={pending:['Bekliyor','Pending'],passed:['Geçti','Passed'],failed:['Kaldı','Failed'],blocked:['Engellendi','Blocked'],open:['Açık','Open'],fixed:['Düzeltildi','Fixed'],retest:['Tekrar test','Retest'],closed:['Kapalı','Closed'],undecided:['Karar verilmedi','Undecided'],approved:['Onaylandı','Approved'],hold:['Beklet','Hold'],rejected:['Reddedildi','Rejected'],Critical:['Kritik','Critical'],High:['Yüksek','High'],Medium:['Orta','Medium'],Low:['Düşük','Low'],test:['Test senaryoları','Test cases'],bug:['Hata raporu','Bug report'],smoke:['Smoke checklist','Smoke checklist'],reg:['Regresyon seti','Regression set'],admin:['Yönetici','Administrator'],qa:['QA','QA'],dev:['Geliştirici','Developer'],pm:['PM','PM'],pmo:['PMO','PMO']};
const name=k=>names[k]?t(...names[k]):k;const badge=k=>`<span class="badge ${esc(k)}">${esc(name(k))}</span>`;
const date=v=>v&&!Number.isNaN(new Date(v).getTime())?new Date(v).toLocaleString(language==='en'?'en-GB':'tr-TR',{dateStyle:'short',timeStyle:'short'}):'—';
const project=()=>state?.projects.find(x=>x.id===projectId);const can=(...roles)=>user?.role==='admin'||roles.includes(user?.role);
const options=(values,current)=>values.map(v=>`<option value="${esc(typeof v==='string'?v:v[0])}" ${current===(typeof v==='string'?v:v[0])?'selected':''}>${esc(typeof v==='string'?name(v):v[1])}</option>`).join('');
const field=(label,control)=>`<label class="field">${esc(label)}${control}</label>`;
const input=(key,value='',extra='')=>`<input name="${key}" value="${esc(value)}" ${extra}>`;
const select=(key,values,current,extra='')=>`<select name="${key}" ${extra}>${options(values,current)}</select>`;
const area=(key,value='',extra='')=>`<textarea name="${key}" ${extra}>${esc(value)}</textarea>`;
const button=(label,action,extra='')=>`<button type="button" class="btn" data-action="${action}" ${extra}>${esc(label)}</button>`;
const personOptions=()=>[['',t('Atanmamış','Unassigned')],...members.map(x=>[x.email,`${x.email} · ${name(x.role)}`])];
function toast(message){const el=$('#message');el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,6000);}
async function api(path,body){const response=await fetch(path.startsWith('/api/')?path:'/api/workspace'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'content-type':'application/json'},credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await response.json();}catch{throw Error(t('Sunucu yanıtı okunamadı','Could not read server response'));}if(!response.ok){if(response.status===401&&user){user=null;state=null;login();}throw Object.assign(Error(data.message||data.error||'Request failed'),{status:response.status});}return data;}
async function command(action,payload){if(busy)throw Error(t('Kayıt sürüyor, lütfen bekle','Save in progress'));busy=true;try{const data=await api('/command',{action,payload:{projectId,...payload},revision:state.revision});state=data.state;toast(t('Kaydedildi','Saved'));return data.state;}catch(e){if(e.status===409){await load();}throw e;}finally{busy=false;}}
async function load(){const data=await api('/state');state=data.state;if(!project())projectId=state.projects[0]?.id||'';}
function showModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="btn" data-action="close-modal" aria-label="${t('Kapat','Close')}">×</button></div>${body}`;if(!modal.open)modal.showModal();}
const empty=message=>`<div class="empty">${esc(message)}</div>`;
function setTheme(){document.documentElement.dataset.theme=theme;pref('qacrew-theme',theme);document.documentElement.lang=language;pref('qs-language',language);}
function login(){setTheme();root.innerHTML=`<main class="login"><div class="intro"><div class="eyebrow">QAcrew Studio / Forge</div><h1>${t('Testi planla.<br>Kararı netleştir','Plan the test.<br>Clarify the decision')}<span class="accent">.</span></h1><p class="muted">${t('Gereksinimden yayın kararına, ekibinle aynı çalışma alanında.','From requirements to release decisions, one shared workspace.')}</p><div class="steps"><span>01 / REQUIREMENT</span><span>02 / TEST</span><span>03 / RELEASE</span></div></div><div class="stack"><div class="toolbar" style="justify-content:flex-end">${button(language==='tr'?'EN':'TR','language')}${button('☼ / ☾','theme')}</div><form id="loginForm" class="card stack"><div><div class="eyebrow">${t('ÇALIŞMA ALANI ÖNİZLEMESİ','WORKSPACE PREVIEW')}</div><h2>${t('Forge’a giriş yap','Sign in to Forge')}</h2><p class="muted">${t('Oturum ve erişim sunucuda doğrulanır.','Sessions and permissions are verified on the server.')}</p></div>${field(t('E-posta','Email'),input('email','', 'type="email" autocomplete="username" required'))}${field(t('Şifre','Password'),input('password','','type="password" autocomplete="current-password" required'))}<p id="loginError" class="error" hidden role="alert"></p><button class="btn primary" type="submit">${t('Giriş yap','Sign in')}</button></form>${config.preview?`<div class="card stack"><b>${t('Önizleme hesapları','Preview accounts')}</b><div class="toolbar">${config.accounts.map(a=>button(name(a.role),'fill-login',`data-email="${esc(a.email)}"`)).join('')}</div><small>${t('Sadece bu önizleme için şifre','Password for this preview only')}: <code>Preview-only-2026!</code></small></div>`:''}</div></main>`;}
const navigation=[['dashboard','Panel','Dashboard'],['requirements','Gereksinimler','Requirements'],['scenarios','Senaryolar','Scenarios'],['plans','Planlar','Plans'],['runs','Koşumlar','Runs'],['bugs','Hatalar','Bugs'],['reports','Raporlar','Reports']];
function projectPicker(){return `<div class="field project-picker"><span id="projectLabel">${t('Proje','Project')}</span><button type="button" id="projectSelect" class="project-trigger" data-action="toggle-projects" aria-haspopup="menu" aria-expanded="false" aria-controls="projectMenu" aria-labelledby="projectLabel projectValue"><span class="project-mark" aria-hidden="true">◈</span><span id="projectValue">${esc(project()?.name||t('Proje seç','Select project'))}</span><span class="project-chevron" aria-hidden="true">⌄</span></button><div id="projectMenu" class="project-menu" role="menu" aria-labelledby="projectLabel" hidden><div class="project-menu-heading" role="presentation">${t('ÇALIŞMA ALANLARIN','YOUR WORKSPACES')}<span>${state.projects.length}</span></div><div class="project-options" role="presentation">${state.projects.map(p=>`<button type="button" role="menuitemradio" aria-checked="${p.id===projectId}" tabindex="-1" class="project-option" data-action="choose-project" data-id="${esc(p.id)}"><span class="project-avatar" aria-hidden="true">${esc(p.name.replace(/^Örnek · /,'').slice(0,2).toLocaleUpperCase())}</span><span class="project-option-name">${esc(p.name)}</span><span class="project-check" aria-hidden="true">${p.id===projectId?'✓':''}</span></button>`).join('')}</div>${can('qa','pm','pmo')?`<div class="project-menu-footer" role="presentation"><button type="button" role="menuitem" tabindex="-1" data-action="new-project"><span class="project-add" aria-hidden="true">+</span>${t('Yeni proje oluştur','Create new project')}</button></div>`:''}</div></div>`;}
function closeProjects(focus=false){const menu=$('#projectMenu');if(menu)menu.hidden=true;$('#projectSelect')?.setAttribute('aria-expanded','false');if(focus)$('#projectSelect')?.focus();}
function openProjects(){const menu=$('#projectMenu');if(!menu)return;menu.hidden=false;$('#projectSelect').setAttribute('aria-expanded','true');(menu.querySelector('[aria-checked="true"]')||menu.querySelector('[role^="menuitem"]'))?.focus();}
document.addEventListener('click',e=>{if(!e.target.closest('.project-picker'))closeProjects();});
document.addEventListener('focusin',e=>{if(!e.target.closest('.project-picker'))closeProjects();});
document.addEventListener('keydown',e=>{if(!e.target.closest('.project-picker'))return;const menu=$('#projectMenu');if(e.key==='Escape'){e.preventDefault();closeProjects(true);return;}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();if(menu.hidden){openProjects();return;}const items=[...menu.querySelectorAll('[role^="menuitem"]')],i=items.indexOf(document.activeElement);if(items.length)items[e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length].focus();}});
function shell(){setTheme();const p=project(),versions=[...new Set((p?.runs||[]).map(r=>r.version).concat((p?.plans||[]).map(r=>r.version)))];if(version&&!versions.includes(version))version='';root.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="/forge/">QAcrew <span>Forge</span></a><nav aria-label="${t('Çalışma akışı','Workflow')}">${navigation.map(([key,tr,en],i)=>`<button class="nav-btn ${tab===key?'active':''}" data-action="nav" data-tab="${key}" aria-current="${tab===key?'page':'false'}"><span>0${i+1}</span><span>${t(tr,en)}</span></button>`).join('')}</nav><div class="bottom">${button(t('Portföy','Portfolio'),'nav','data-tab="portfolio"')}${button(t('Yedek ve aktarım','Backup & import'),'backup')}<small>${esc(user.email)}<br>${badge(user.role)}</small><small>${t('Sunucuda saklanır · ekipçe paylaşılır','Server storage · shared with your team')}</small></div></aside><header class="topbar"><div class="toolbar">${projectPicker()}${field(t('Sürüm','Release'),select('version',[['',t('Tüm sürümler','All releases')],...versions],version,'id="versionSelect"'))}</div><div class="utility">${button(t('Yenile','Refresh'),'refresh')}${button(language==='tr'?'EN':'TR','language')}${button('☼ / ☾','theme')}${button(t('Portföy','Portfolio')+' · '+name(user.role),'nav','data-tab="portfolio"')}${button(t('Çıkış','Sign out'),'logout')}</div></header><main class="workspace" id="main">${config.preview?`<p class="note no-print">${t('Önizleme · Canlı siteyi etkilemez. Örnek hesaplar aynı yerel sunucu çalışma alanını paylaşır.','Preview · Does not affect the live site. Sample accounts share this local server workspace.')}</p>`:''}<div id="content"></div></main></div>`;renderContent();}
function heading(title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${esc(project()?.name||'QAcrew Forge')}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="toolbar">${actions}</div></div>`;}
function renderContent(){const el=$('#content');if(!el)return;if(!project()&&tab!=='portfolio'){el.innerHTML=heading(t('Yeni bir projeyle başla','Start with a project'),t('Gereksinimden rapora bütün kayıtlar projeye bağlıdır.','Every record belongs to a project.'),can('qa','pm','pmo')?button(t('Proje oluştur','Create project'),'new-project'):'');return;}const renderers={dashboard:dashboard,requirements:requirements,scenarios:scenarios,plans:plans,runs:runs,bugs:bugs,reports:reports,portfolio:portfolio};el.innerHTML=(renderers[tab]||dashboard)();}
function counts(runs){const cases=runs.flatMap(r=>r.cases);return {total:cases.length,...Object.fromEntries(['passed','failed','blocked','pending'].map(s=>[s,cases.filter(c=>c.status===s).length]))};}
function stat(value,label){return `<div class="stat"><small>${esc(label)}</small><strong>${esc(value)}</strong></div>`;}
function dashboard(){const p=project(),rs=p.runs.filter(r=>!version||r.version===version),c=counts(rs);return heading(t('Bugün neyi güvenle yayınlayabiliriz?','What can we confidently release today?'),t('Sonuçlar yalnızca kaydedilmiş test yürütmelerinden hesaplanır.','Metrics are calculated from recorded test executions.'),button(t('Yeni doküman','New document'),'new-document'))+`<div class="stack"><div class="stats">${stat(p.documents.length,t('Kaydedilen doküman','Saved documents'))}${stat(c.total,t('Test yürütmesi','Test executions'))}${stat(c.passed,t('Geçti','Passed'))}${stat(p.bugs.filter(b=>b.status!=='closed').length,t('Açık hata','Open bugs'))}</div><div class="two"><section class="card"><div class="toolbar spread"><h2>${t('Sıradaki işler','Next actions')}</h2>${badge('pending')}</div><div class="list">${rs.flatMap(r=>r.cases.filter(x=>x.status==='pending').slice(0,3).map(c=>`<div class="list-row"><div><h3>${esc(c.title)}</h3><small>${esc(r.version)} · ${esc(c.assignee||t('Atanmamış','Unassigned'))}</small></div>${button(t('Devam et','Continue'),'open-run',`data-id="${r.id}"`)}</div>`)).slice(0,5).join('')||empty(t('Bekleyen yürütme yok. Senaryolarını planla.','No pending executions. Plan your scenarios.'))}</div></section><section class="card"><h2>${t('Kapsam ve risk','Coverage & risk')}</h2><p>${t('Gereksinim','Requirements')}: <b>${p.requirements.length}</b> · ${t('Senaryo','Scenarios')}: <b>${p.scenarios.length}</b></p><p>${t('Testi olmayan gereksinim','Requirements without tests')}: <b>${p.requirements.filter(r=>!p.scenarios.some(s=>s.requirementId===r.id)).length}</b></p><p>${t('Kaldı / Engellendi / Bekliyor','Failed / Blocked / Pending')}: <b>${c.failed} / ${c.blocked} / ${c.pending}</b></p><p class="note">${t('Kısa bir koşumun bitmesi ürün genelinin test edildiği anlamına gelmez.','Completing a short run does not mean the whole product has been tested.')}</p></section></div><section class="card"><h2>${t('Son işlemler','Recent activity')}</h2><ul class="history">${state.audit.filter(a=>a.projectId===projectId).slice(-6).reverse().map(a=>`<li><b>${esc(a.by)}</b> · ${esc(actionName(a.action))}<br><small>${date(a.at)}</small></li>`).join('')||`<li>${t('Henüz işlem yok','No activity yet')}</li>`}</ul></section></div>`;}
function actionName(action){const map={'requirement.save':['Gereksinim kaydedildi','Requirement saved'],'scenario.save':['Senaryo kaydedildi','Scenario saved'],'scenario.import':['Senaryolar aktarıldı','Scenarios imported'],'document.save':['Doküman kaydedildi','Document saved'],'plan.save':['Plan kaydedildi','Plan saved'],'run.create':['Koşum başlatıldı','Run started'],'run.result':['Test sonucu kaydedildi','Test result saved'],'run.bulk':['Toplu sonuç kaydedildi','Bulk result saved'],'bug.update':['Hata güncellendi','Bug updated'],'retest.save':['Tekrar test yapıldı','Retest completed'],'decision.save':['Yayın kararı verildi','Release decision recorded']};return map[action]?t(...map[action]):t('Kayıt güncellendi','Record updated');}
function requirements(){const p=project();return heading(t('Gereksinimleri netleştir','Clarify requirements'),t('Kaynağı, açık soruları ve bağlı senaryoları birlikte izle.','Track sources, open questions and linked scenarios together.'),can('qa','pm')?button(t('Yeni gereksinim','New requirement'),'new-requirement'):'')+`<div class="list">${p.requirements.map(r=>`<article class="card"><div class="toolbar spread"><div><h2>${esc(r.title)}</h2><small>${date(r.updatedAt)} · ${esc(r.updatedBy)}</small></div><div class="toolbar">${button(t('Aç / yanıtla','Open / answer'),'edit-requirement',`data-id="${r.id}"`)}${can('qa')?button(t('Senaryo üret','Create scenarios'),'from-requirement',`data-id="${r.id}"`):''}</div></div><p class="long">${esc(r.input.slice(0,250))}</p><div class="toolbar"><span class="badge">${r.questions.filter(q=>q.status!=='confirmed').length} ${t('açık soru','open questions')}</span><span class="badge">${p.scenarios.filter(s=>s.requirementId===r.id).length} ${t('bağlı senaryo','linked scenarios')}</span></div></article>`).join('')||empty(t('İlk gereksinimini ekle veya GitHub iş kaleminden getir.','Add a requirement or import a GitHub issue.'))}</div>`;}
function requirementEditor(id){const r=project().requirements.find(x=>x.id===id)||{title:'',input:'',source:'',questions:[]};showModal(t('Gereksinim ve açık sorular','Requirement & open questions'),`<form id="requirementForm" class="stack" data-id="${id||''}">${field(t('Başlık','Title'),input('title',r.title,'required maxlength="200"'))}${field(t('Kaynak bağlantısı','Source link'),input('source',r.source))}<div class="toolbar">${input('issue','','type="number" min="1" placeholder="GitHub #" style="width:140px"')}${button(t('GitHub’dan getir','Import from GitHub'),'github-import')}</div>${field(t('Gereksinim metni','Requirement text'),area('input',r.input,'required maxlength="12000" rows="6"'))}${button(t('Açık soruları çıkar','Identify open questions'),'scan-questions')}<small>${t('Kural tabanlı kontrol; kaynakta olmayan iş kuralı eklenmez.','Rule-based check; no unstated business rules are added.')}</small><div id="questionEditor" class="stack">${questionFields(r.questions)}</div>${can('qa','pm')?'<button type="submit" class="btn primary">'+t('Gereksinimi kaydet','Save requirement')+'</button>':''}</form>`);}
function questionFields(list){return list.map(q=>`<article class="card question"><b data-question>${esc(q.question)}</b>${field(t('Yanıt','Answer'),area('answer',q.answer||''))}${field(t('Durum','Status'),select('questionStatus',[['open',t('Açık','Open')],['confirmed',t('Doğrulandı','Confirmed')],['unknown',t('Henüz belli değil','Not decided yet')]],q.status||'open'))}</article>`).join('');}
function questionList(input){const list=[t('Başarı ölçütü ve hata durumundaki beklenen davranış nedir?','What are the success criteria and expected failure behavior?'),t('Hangi platform, sürüm ve ortamlar kapsamda?','Which platforms, versions and environments are in scope?')];if(/kupon|coupon|indirim|discount/i.test(input))list.push(t('Kuponun alt tutar, kullanım ve birleştirme sınırları nedir?','What are the coupon minimum, reuse and stacking rules?'));if(/ödeme|payment|checkout/i.test(input))list.push(t('Zaman aşımı, yeniden deneme ve çift tahsilat nasıl ele alınmalı?','How should timeouts, retries and duplicate charges be handled?'));if(/giriş|login|password|parola/i.test(input))list.push(t('Hatalı giriş denemesi ve oturum süresi sınırları nedir?','What are the failed-login and session-expiry limits?'));return list.map(question=>({question,status:'open',answer:''}));}
function scenarios(){const p=project();return heading(t('Senaryolar ve dokümanlar','Scenarios & documents'),t('Taslağı düzenle, soruları yanıtla ve onaylayarak kütüphaneye al.','Edit drafts, answer questions, then approve them for the library.'),can('qa')?button(t('Yeni doküman','New document'),'new-document'):'')+`<div class="subnav">${button(t('Senaryo kütüphanesi','Scenario library'),'scenario-sub','data-sub="library"')}${button(t('Dokümanlar','Documents')+` (${p.documents.length})`,'scenario-sub','data-sub="documents"')}${button(t('Şablonlar','Templates'),'scenario-sub','data-sub="templates"')}</div>`+(subtab==='documents'?documents():subtab==='templates'?`<div class="grid">${['test','bug','smoke','reg'].map(type=>`<article class="card"><div class="eyebrow">${type.toUpperCase()}</div><h2>${name(type)}</h2><p class="muted">${t('Düzenlenebilir doküman ve açık sorular.','Editable document with open questions.')}</p>${button(t('Bu şablonu kullan','Use this template'),'new-document',`data-type="${type}"`)}</article>`).join('')}</div><p class="note">${t('Test planları Planlar, metrikler Panel ve Raporlar altında. API, senaryolarda platform seçeneğidir; ayrı bir üretim türü vaat edilmez.','Test plans live under Plans, metrics under Dashboard and Reports. API is a scenario platform, not a separate generation type.')}</p>`:`<div class="toolbar" style="margin-bottom:18px">${can('qa')?button(t('Yeni senaryo','New scenario'),'new-scenario')+button(t('CSV / Excel içe aktar','Import CSV / Excel'),'import-scenarios'):''}${button(t('CSV indir','Download CSV'),'export-scenarios')}</div><div class="list">${p.scenarios.map(s=>`<article class="card"><div class="toolbar spread"><div><h3>${esc(s.title)}</h3><div class="toolbar">${badge(s.priority)}<span class="badge">${esc(s.platform)}</span>${s.approved?badge('approved'):`<span class="badge">${t('Taslak','Draft')}</span>`}</div></div>${button(t('Düzenle','Edit'),'edit-scenario',`data-id="${s.id}"`)}</div><p>${esc(s.expected)}</p><small>${t('Gereksinim','Requirement')}: ${esc(p.requirements.find(r=>r.id===s.requirementId)?.title||t('Bağlantı yok','Not linked'))} · ${s.estimate} ${t('dk','min')}</small></article>`).join('')||empty(t('Henüz senaryo yok. Dokümandan ekleyebilir veya CSV/Excel içe aktarabilirsin.','No scenarios yet. Add from a document or import CSV/Excel.'))}</div>`);}
function documents(){let docs=project().documents.filter(d=>(docType==='all'||d.type===docType)&&(!docQuery||d.title.toLocaleLowerCase().includes(docQuery.toLocaleLowerCase())));docs.sort(docSort==='title'?(a,b)=>a.title.localeCompare(b.title):(a,b)=>b.updatedAt.localeCompare(a.updatedAt));return `<div class="toolbar" style="margin-bottom:18px">${field(t('Ara','Search'),input('docSearch',docQuery,'id="docSearch" type="search"'))}${field(t('Tür','Type'),select('docType',[['all',t('Tümü','All')],'test','bug','smoke','reg'],docType,'id="docType"'))}${field(t('Sıralama','Sort'),select('docSort',[['date',t('Son güncellenen','Recently updated')],['title',t('Başlık A–Z','Title A–Z')]],docSort,'id="docSort"'))}</div><div class="list">${docs.map(d=>`<div class="list-row"><div><h3>${esc(d.title)}</h3><small>${esc(name(d.type))} · ${esc(d.platform)} · ${d.language.toUpperCase()} · ${date(d.updatedAt)}</small></div>${button(t('Aç / düzenle','Open / edit'),'edit-document',`data-id="${d.id}"`)}</div>`).join('')||empty(t('Eşleşen doküman yok.','No matching documents.'))}</div>`;}
function scenarioEditor(id){const s=project().scenarios.find(x=>x.id===id)||{title:'',steps:[],expected:'',priority:'Medium',platform:'Web',estimate:5,approved:false};showModal(t('Senaryo','Scenario'),`<form id="scenarioForm" class="stack" data-id="${id||''}">${field(t('Başlık','Title'),input('title',s.title,'required'))}${field(t('Gereksinim','Requirement'),select('requirementId',[['',t('Bağlantı yok','Not linked')],...project().requirements.map(r=>[r.id,r.title])],s.requirementId))}${field(t('Ön koşul','Precondition'),area('preconditions',s.preconditions))}${field(t('Adımlar (her satıra bir adım)','Steps (one per line)'),area('steps',s.steps.join('\n'),'required'))}${field(t('Beklenen sonuç','Expected result'),area('expected',s.expected,'required'))}<div class="grid">${field(t('Öncelik','Priority'),select('priority',['Critical','High','Medium','Low'],s.priority))}${field('Platform',select('platform',['Web','Android','iOS','API'],s.platform))}${field(t('Tahmin (dk)','Estimate (min)'),input('estimate',s.estimate,'type="number" min="1" max="240" required'))}</div><label class="inline-field"><input type="checkbox" name="approved" ${s.approved?'checked':''}>${t('Gözden geçirildi, planlamaya hazır','Reviewed and ready for planning')}</label>${can('qa')?`<button class="btn primary" type="submit">${t('Senaryoyu kaydet','Save scenario')}</button>`:''}</form>`);}
function documentCreator(requirementId,type='test'){const r=project().requirements.find(x=>x.id===requirementId);showModal(t('Yeni doküman','New document'),`<form id="generateForm" class="stack"><div class="grid">${field(t('Çıktı türü','Output type'),select('type',['test','bug','smoke','reg'],type))}${field('Platform',select('platform',['Web','Android','iOS','API'],'Web'))}${field(t('Doküman dili','Document language'),select('language',[['tr','Türkçe'],['en','English']],language))}${field(t('Kapsam','Scope'),select('depth',[['quick',t('Standart','Standard')],['deep',t('Detaylı','Detailed')]],'quick'))}</div>${field(t('Gereksinim bağlantısı','Requirement link'),select('requirementId',[['',t('Bağlantı yok','Not linked')],...project().requirements.map(r=>[r.id,r.title])],r?.id||''))}${field(t('Başlık','Title'),input('title',r?.title||'','required maxlength="200"'))}${field(t('Girdi','Input'),area('input',r?.input||'','required maxlength="12000" rows="6"'))}<div class="toolbar spread">${button(t('Hazır örnekle dene','Use sample input'),'sample-input')}<small id="inputCount">${(r?.input||'').length} / 12000</small></div><p class="note">${config.ai?t('Forge AI, sunucudaki model bağlantısını kullanır. Çıktıları onaylamadan önce kontrol et.','Forge AI uses the server model connection. Review output before approval.'):t('Bu önizleme girdinden düzenlenebilir, kural tabanlı bir taslak hazırlar. Yapay zekâ üretimi veya doğrulanmış test sonucu değildir.','This preview creates an editable rule-based draft from your input. It is not AI generation or a verified test result.')}</p><button class="btn primary" type="submit">${t('Taslak oluştur','Create draft')}</button><p id="generationError" role="alert" class="error" hidden></p></form>`);}
function documentEditor(doc){draft=structuredClone(doc);showModal(t('Dokümanı düzenle','Edit document'),`<form id="documentForm" class="stack"><div class="toolbar spread"><div>${badge(doc.type)} <span class="badge">${esc(doc.platform)}</span> <span class="badge">${doc.language.toUpperCase()}</span></div><small>${doc.sample?t('Kural tabanlı taslak · gözden geçir','Rule-based draft · review required'):t('Forge AI çıktısı · gözden geçir','Forge AI output · review required')}</small></div>${field(t('Başlık','Title'),input('title',doc.title,'required'))}<div id="documentRows" class="stack">${doc.rows.map((r,i)=>`<article class="editor-row"><div class="row-head"><b>${i+1}</b>${field(t('Öncelik','Priority'),select('priority',['Critical','High','Medium','Low'],r.priority))}</div>${field(t('Senaryo / madde','Scenario / item'),input('rowTitle',r.title,'required'))}${field(t('Adımlar / açıklama','Steps / description'),area('steps',r.steps))}${field(t('Beklenen sonuç / kapsam','Expected result / scope'),area('expected',r.expected))}</article>`).join('')}</div><h3>${t('Eksik bilgi ve kararlar','Missing information & decisions')}</h3>${doc.questions.map(q=>`<label class="field doc-question"><span>${esc(q.question)}</span>${area('answer',q.answer)}</label>`).join('')||`<p class="muted">${t('Açık soru yok.','No open questions.')}</p>`}<div class="toolbar"><button class="btn primary" type="submit">${t('Dokümanı kaydet','Save document')}</button>${button(t('Onayla ve kütüphaneye ekle','Approve & add to library'),'approve-document')}${button(t('CSV indir','Download CSV'),'export-document')}</div></form>`);}
function readDocument(){const form=$('#documentForm');return {...draft,title:form.elements.title.value,rows:$$('#documentRows .editor-row').map(r=>({title:r.querySelector('[name=rowTitle]').value,steps:r.querySelector('[name=steps]').value,expected:r.querySelector('[name=expected]').value,priority:r.querySelector('[name=priority]').value})),questions:$$('.doc-question').map(q=>({question:q.querySelector('span').textContent,answer:q.querySelector('textarea').value}))};}
function plans(){const p=project();return heading(t('Sürüm planları','Release plans'),t('Onaylı senaryoları seç, süreyi gör ve sorumluları ata.','Select approved scenarios, review the budget and assign owners.'),can('qa','pm')?button(t('Yeni plan','New plan'),'new-plan'):'')+`<div class="list">${p.plans.filter(x=>!version||x.version===version).map(plan=>{const estimate=plan.scenarioIds.reduce((n,id)=>n+(p.scenarios.find(s=>s.id===id)?.estimate||0),0);return `<article class="card"><div class="toolbar spread"><div><h2>${esc(plan.title)}</h2><small>${esc(plan.version)} · ${esc(plan.environment)} · ${esc(plan.platform)}</small></div><div class="toolbar">${button(t('Düzenle','Edit'),'edit-plan',`data-id="${plan.id}"`)}${can('qa')?button(t('Yürütme başlat','Start run'),'start-run',`data-id="${plan.id}"`):''}</div></div><p>${plan.scenarioIds.length} ${t('senaryo','scenarios')} · ${estimate} / ${plan.budget} ${t('dk tahmini süre','min estimated')}</p>${estimate>plan.budget?`<p class="note">${t('Plan süre bütçesini aşıyor. Kapsamı gözden geçir.','Plan exceeds its time budget. Review the scope.')}</p>`:''}</article>`;}).join('')||empty(t('Henüz plan yok. Önce kütüphaneye onaylı senaryolar ekle.','No plans yet. First approve scenarios in the library.'))}</div>`;}
function planEditor(id){const p=project(),plan=p.plans.find(x=>x.id===id)||{title:'',version:version||'',environment:'',platform:'Web',notes:'',budget:30,scenarioIds:[],assignments:{}};showModal(t('Sürüm planı','Release plan'),`<form id="planForm" class="stack" data-id="${id||''}">${field(t('Proje','Project'),input('projectName',p.name,'disabled'))}<div class="grid">${field(t('Plan adı','Plan name'),input('title',plan.title,'required'))}${field(t('Sürüm','Release'),input('version',plan.version,'required'))}${field(t('Ortam','Environment'),input('environment',plan.environment,'required placeholder="Staging · Chrome 130"'))}${field('Platform',select('platform',['Web','Android','iOS','API'],plan.platform))}${field(t('Süre bütçesi (dk)','Time budget (min)'),input('budget',plan.budget,'type="number" min="1" max="14400" required'))}</div>${field(t('Sürüm notu / değişen modüller','Release notes / changed modules'),area('notes',plan.notes))}${button(t('Sürüm notuna göre öner','Suggest from release notes'),'suggest-plan')}<small>${t('Öneri, yalnız başlık ve sürüm notu sözcük eşleşmesidir; kod/bağımlılık analizi değildir.','Suggestions use title/notes keyword matching only, not code or dependency analysis.')}</small><div id="planCases">${p.scenarios.filter(s=>s.approved).map(s=>`<div class="check-row"><input type="checkbox" name="scenario" value="${s.id}" ${plan.scenarioIds.includes(s.id)?'checked':''} aria-label="${esc(s.title)}"><div><b>${esc(s.title)}</b><small>${esc(s.platform)} · ${name(s.priority)} · ${s.estimate} ${t('dk','min')}</small></div>${select('assignee-'+s.id,personOptions(),plan.assignments[s.id]||'',`aria-label="${t('Sorumlu','Assignee')} ${esc(s.title)}"`)}</div>`).join('')||empty(t('Onaylı senaryo bulunmuyor.','No approved scenarios.'))}</div><p class="note" id="planBudget"></p><p class="error" role="alert" id="planError" hidden></p><button type="submit" class="btn primary">${t('Planı kaydet','Save plan')}</button></form>`);planBudget();}
function planBudget(){const form=$('#planForm');if(!form)return;const selected=[...form.querySelectorAll('[name=scenario]:checked')].map(x=>x.value),sum=project().scenarios.filter(s=>selected.includes(s.id)).reduce((n,s)=>n+s.estimate,0),budget=Number(form.elements.budget.value)||0;$('#planBudget').textContent=`${t('Seçilen tahmini süre','Estimated selected time')}: ${sum} / ${budget} ${t('dk','min')}${sum>budget?' · '+t('Bütçe aşıldı','Over budget'):''}`;}
function runs(){const p=project(),run=p.runs.find(r=>r.id===activeRun);if(run)return runView(run);return heading(t('Test koşumları','Test runs'),t('Her koşum, senaryoların o andaki değişmez kopyasıdır.','Each run is an immutable snapshot of its scenarios.'))+`<div class="list">${p.runs.filter(r=>!version||r.version===version).map(r=>{const c=counts([r]);return `<div class="list-row"><div><h2>${esc(r.title)}</h2><small>${esc(r.version)} · ${esc(r.platform)} · ${esc(r.environment)}</small><p>${c.passed}/${c.total} ${t('geçti','passed')} · ${c.failed} ${t('kaldı','failed')} · ${c.pending} ${t('bekliyor','pending')}</p></div>${button(t('Aç / devam et','Open / continue'),'open-run',`data-id="${r.id}"`)}</div>`;}).join('')||empty(t('Planlar ekranından bir koşum başlat.','Start a run from Plans.'))}</div>`;}
function runView(run){const cases=run.cases.filter(c=>runFilter==='all'||c.status===runFilter);return heading(run.title,`${run.version} · ${run.platform} · ${run.environment}`,button(t('Koşumlara dön','Back to runs'),'close-run'))+`<div class="toolbar no-print" style="margin-bottom:18px">${field(t('Sonuç filtresi','Result filter'),select('runFilter',[['all',t('Tümü','All')],'pending','passed','failed','blocked'],runFilter,'id="runFilter"'))}${button(t('Kaldığım yerden devam','Resume pending'),'resume-run')}${can('qa')?button(t('Seçilen bekleyenleri geçti işaretle','Pass selected pending cases'),'bulk-pass'):''}<small>Alt+P: ${t('Geçti','Pass')} · Alt+F: ${t('Kaldı','Fail')} · Alt+B: ${t('Engel','Block')} · Alt+N: ${t('Sonraki','Next')}</small></div><div class="stack" id="runCases">${cases.map(c=>`<article class="card run-case" id="case-${c.id}" tabindex="-1"><div class="toolbar spread"><div class="toolbar"><input type="checkbox" name="bulkCase" value="${c.id}" ${c.status!=='pending'?'disabled':''} aria-label="${t('Toplu işlem için seç','Select for bulk action')} ${esc(c.title)}"><h2>${esc(c.title)}</h2></div><div class="toolbar">${badge(c.priority)}${badge(c.status)}</div></div><small>${t('Sorumlu','Assignee')}: ${esc(c.assignee||'—')} · ${t('Senaryo','Scenario')}: ${esc(c.scenarioId.slice(0,8))}</small><details><summary>${t('Adımlar ve beklenen sonuç','Steps & expected result')}</summary><p>${esc(c.preconditions)}</p><ol>${c.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><b>${t('Beklenen','Expected')}:</b> ${esc(c.expected)}</p></details><form class="resultForm stack" data-case="${c.id}" data-run="${run.id}"><div class="case-grid"><div>${field(t('Test notu (Kaldı / Engellendi için zorunlu)','Test note (required for Failed / Blocked)'),area('note',c.note,'maxlength="5000"'))}<span class="counter">${(c.note||'').length} ${t('karakter · en az 10 (Kaldı / Engellendi)','characters · minimum 10 (Failed / Blocked)')}</span>${field(t('Kanıt: ekran görüntüsü, video veya log (dosya başına 5 MB)','Evidence: screenshot, video or log (5 MB per file)'),'<input type="file" name="evidence" accept="image/png,image/jpeg,image/webp,video/mp4,video/webm,.txt,.log" multiple>')}<div class="evidence">${(c.evidence||[]).map((id,i)=>button(t('Kanıt','Evidence')+' '+(i+1),'evidence',`data-id="${esc(id)}"`)).join('')}</div></div><div class="case-result">${field(t('Sonuç','Result'),select('status',['pending','passed','failed','blocked'],c.status))}${can('qa')?`<button class="btn primary" type="submit">${t('Sonucu kaydet','Save result')}</button>`:''}<small>${c.executedAt?date(c.executedAt)+' · '+esc(c.executedBy):t('Henüz yürütülmedi','Not executed yet')}</small></div></div><div class="bug-inline" ${c.status==='failed'?'':'hidden'}><h3>${t('Bu teste bağlı hata','Bug linked to this test')}</h3><div class="grid">${field(t('Hata başlığı','Bug title'),input('bugTitle',c.title))}${field(t('Önem','Severity'),select('severity',['Critical','High','Medium','Low'],c.priority))}${field(t('Atanan geliştirici','Assigned developer'),select('assignee',personOptions(),''))}</div><small>${t('Aynı testte açık hata varsa ikinci kez oluşturulmaz.','An existing open bug for this test will not be duplicated.')}</small></div><p class="error" role="alert" hidden></p></form></article>`).join('')||empty(t('Bu filtrede test yok.','No tests match this filter.'))}</div>`;}
function bugs(){const p=project(),items=p.bugs.filter(b=>(!version||b.version===version)&&(bugFilter==='all'||bugFilter==='mine'&&b.assignee===user.email||b.status===bugFilter));return heading(t('Hatalar','Bugs'),t('Düzeltme build’i, açık tekrar test ve kapanış geçmişi.','Fixed build, explicit retest and closure history.'))+`<div class="toolbar" style="margin-bottom:18px">${field(t('Filtre','Filter'),select('bugFilter',[['all',t('Tümü','All')],['mine',t('Bana atananlar','Assigned to me')],'open','fixed','retest','closed'],bugFilter,'id="bugFilter"'))}</div><div class="list">${items.map(b=>`<article class="card"><div class="toolbar spread"><div><div class="eyebrow">BUG / ${esc(b.id.slice(0,8))}</div><h2>${esc(b.title)}</h2></div>${button(t('Aç','Open'),'open-bug',`data-id="${b.id}"`)}</div><div class="toolbar">${badge(b.status)}${badge(b.severity)}<span class="badge">${esc(b.version)}</span></div><p>${esc(b.actual)}</p><small>${t('Atanan','Assigned')}: ${esc(b.assignee||'—')} · ${t('Düzeltme build’i','Fixed build')}: ${esc(b.fixedBuild||'—')}</small></article>`).join('')||empty(t('Bu filtrede hata yok.','No matching bugs.'))}</div>`;}
function bugEditor(id){const b=project().bugs.find(x=>x.id===id);if(!b)return;showModal(t('Hata ayrıntısı','Bug details'),`<div class="stack"><div><div class="eyebrow">BUG / ${esc(b.id.slice(0,8))}</div><h2>${esc(b.title)}</h2><div class="toolbar">${badge(b.severity)}${badge(b.status)}<span class="badge">${esc(b.version)} · ${esc(b.platform)}</span></div></div><p><b>${t('Gerçekleşen','Actual')}:</b> ${esc(b.actual)}<br><b>${t('Beklenen','Expected')}:</b> ${esc(b.expected)}</p><ol>${b.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><small>${esc(b.environment)}</small><div class="toolbar">${button(t('Bağlantıyı kopyala','Copy link'),'bug-link',`data-id="${b.id}"`)}${button('GitHub','github-export',`data-id="${b.id}"`)}${button(t('Jira / Azure CSV','Jira / Azure CSV'),'bug-csv',`data-id="${b.id}"`)}${button(t('Koşumu aç','Open run'),'bug-run',`data-id="${b.runId}"`)}</div><div class="evidence">${(b.evidence||[]).map((id,i)=>button(t('Kanıt','Evidence')+' '+(i+1),'evidence',`data-id="${id}"`)).join('')}</div>${can('qa','dev')?`<form id="bugForm" class="stack" data-id="${b.id}"><div class="grid">${field(t('Durum','Status'),select('status',['open','fixed',...(can('qa')?['retest']:[])],b.status))}${field(t('Düzeltme build’i','Fixed build'),input('fixedBuild',b.fixedBuild))}${field(t('Atanan','Assigned'),select('assignee',personOptions(),b.assignee))}</div>${field(t('Geliştirici notu','Developer note'),area('note',''))}<button class="btn primary" type="submit">${t('Hatayı güncelle','Update bug')}</button></form>`:''}${can('qa')&&['fixed','retest'].includes(b.status)?`<form id="retestForm" class="stack card" data-id="${b.id}"><h3>${t('QA tekrar testi','QA retest')}</h3>${field(t('Tekrar test notu (en az 10 karakter)','Retest note (at least 10 characters)'),area('note','','required minlength="10"'))}${field(t('Tekrar test sonucu','Retest result'),select('passed',[['true',t('Geçti → kapat','Passed → close')],['false',t('Kaldı → yeniden aç','Failed → reopen')]],'false'))}<button class="btn primary" type="submit">${t('Tekrar test sonucunu kaydet','Save retest result')}</button></form>`:''}<h3>${t('İşlem geçmişi','History')}</h3><ul class="history">${b.history.map(h=>`<li>${badge(h.status)} · ${esc(h.by)} · ${date(h.at)}<p>${esc(h.note||'')} ${h.build?'· '+esc(h.build):''}</p></li>`).join('')}</ul></div>`);}
function reportBody(data){const c=counts(data.runs),decision=data.decision;return `<div class="report stack"><div class="stats">${stat(c.total,t('Toplam test','Total tests'))}${stat(c.passed,t('Geçti','Passed'))}${stat(c.failed,t('Kaldı','Failed'))}${stat(c.blocked+c.pending,t('Engel / bekleyen','Blocked / pending'))}</div><div class="card"><h2>${t('Yayın kararı','Release decision')}</h2>${decision?`${badge(decision.status)}<p>${esc(decision.note)}</p><small>${esc(decision.by)} · ${date(decision.at)}${decision.imported?' · '+t('Yedekten alındı','Restored from backup'):''}</small>`:`<p>${t('Henüz karar verilmedi.','No decision yet.')}</p>`}<p class="note">${t('Bu rapor seçilen sürüm, ortam ve koşum kapsamıyla sınırlıdır.','This report is limited to the selected release, environments and runs.')}</p></div>${data.runs.map(r=>`<section class="card"><h2>${esc(r.title)}</h2><p class="muted">${esc(r.version||data.version)} · ${esc(r.platform)} · ${esc(r.environment)}</p><div class="table-scroll"><table><thead><tr><th>${t('Test','Test')}</th><th>${t('Öncelik','Priority')}</th><th>${t('Sonuç','Result')}</th><th>${t('Not / sorumlu','Note / executor')}</th></tr></thead><tbody>${r.cases.map(c=>`<tr><td>${esc(c.title)}</td><td>${badge(c.priority)}</td><td>${badge(c.status)}</td><td>${esc(c.note||'—')}<br><small>${esc(c.executedBy||'—')} · ${date(c.executedAt)}</small></td></tr>`).join('')}</tbody></table></div></section>`).join('')}<section class="card"><h2>${t('Hata durumu','Bug status')}</h2>${data.bugs.length?data.bugs.map(b=>`<div class="list-row"><b>${esc(b.title)}</b><div>${badge(b.severity)} ${badge(b.status)}</div></div>`).join(''):`<p>${t('Kayıtlı hata yok.','No recorded bugs.')}</p>`}</section></div>`;}
function reportData(){const p=project(),v=version||p.runs.at(-1)?.version||'';return {project:p.name,version:v,runs:p.runs.filter(r=>r.version===v),bugs:p.bugs.filter(b=>b.version===v),decision:p.decisions.filter(d=>d.version===v).at(-1)||null};}
function reports(){const data=reportData();return heading(t('Sürüm raporu ve karar','Release report & decision'),`${project().name} · ${data.version||t('Sürüm yok','No release')}`,button(t('Yazdır / PDF','Print / PDF'),'print')+button(t('HTML indir','Download HTML'),'report-html')+button(t('Paylaşılabilir link','Shareable link'),'share-report'))+(data.runs.length?reportBody(data)+(can('pm','pmo')?`<form id="decisionForm" class="card stack no-print" style="margin-top:20px"><h2>${t('Kararı kaydet','Record decision')}</h2>${field(t('Karar','Decision'),select('status',['undecided','approved','hold','rejected'],data.decision?.status||'undecided'))}${field(t('Gerekçe','Reason'),area('note','','required'))}<small>${t('Karar, oturum açmış kişinin adı ve sunucu zamanı ile kaydedilir.','The decision records the signed-in person and server timestamp.')}</small><button type="submit" class="btn primary">${t('Yayın kararını kaydet','Save release decision')}</button></form>`:'')+`<section class="card" style="margin-top:20px"><h2>${t('Gereksinim izlenebilirliği','Requirement traceability')}</h2><div class="table-scroll"><table><thead><tr><th>${t('Gereksinim','Requirement')}</th><th>${t('Senaryolar','Scenarios')}</th><th>${t('Koşum kapsamı','Run coverage')}</th></tr></thead><tbody>${project().requirements.map(r=>{const ids=project().scenarios.filter(s=>s.requirementId===r.id).map(s=>s.id),cases=data.runs.flatMap(run=>run.cases).filter(c=>c.requirementId===r.id);return `<tr><td>${esc(r.title)}</td><td>${ids.length}</td><td>${cases.length} ${t('yürütme','executions')} · ${cases.filter(c=>c.status==='passed').length} ${t('geçti','passed')}</td></tr>`;}).join('')}</tbody></table></div></section>`:empty(t('Rapor için önce bir sürüm koşumu oluştur.','Create a release run before reporting.')));}
function portfolio(){return heading(t('Proje portföyü','Project portfolio'),t('Tüm projeler, sürüm eğilimi ve ekip sorumlulukları.','All projects, release trends and team responsibilities.'),button(t('Yedek ve aktarım','Backup & import'),'backup'))+`<div class="grid">${state.projects.map(p=>{const c=counts(p.runs),versions=[...new Set(p.runs.map(r=>r.version))].slice(-6);return `<article class="card stack"><div class="toolbar spread"><h2>${esc(p.name)}</h2>${button(t('Projeyi aç','Open project'),'switch-project',`data-id="${p.id}"`)}</div><div class="toolbar">${badge('passed')} ${c.passed}/${c.total} · ${p.bugs.filter(b=>b.status!=='closed').length} ${t('açık hata','open bugs')}</div><div class="trend">${versions.map(v=>{const count=counts(p.runs.filter(r=>r.version===v)),pct=count.total?Math.round(count.passed/count.total*100):0;return `<div><small>${pct}%</small><div class="bar" style="--height:${Math.max(3,pct)}px"></div><b>${esc(v)}</b></div>`;}).join('')||`<small>${t('Henüz sürüm geçmişi yok','No release history yet')}</small>`}</div><small>${t('Geçme oranı yalnızca o sürümdeki kaydedilmiş koşumlara dayanır.','Pass rate reflects recorded runs in that release only.')}</small></article>`;}).join('')||empty(t('Henüz proje yok.','No projects yet.'))}</div><section class="card" style="margin-top:22px"><h2>${t('Ekip ve yetkiler','Team & permissions')}</h2><div class="list">${members.map(m=>`<div class="list-row"><b>${esc(m.email)}</b>${badge(m.role)}</div>`).join('')}</div><p class="muted">${t('QA testleri yürütür; geliştirici hatayı düzeltir; PM/PMO karar verir. Yetkiler sunucuda uygulanır.','QA executes tests; developers fix bugs; PM/PMO record release decisions. Permissions are enforced on the server.')}</p></section>`;}
function download(content,filename,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast(t('Bağlantı kopyalandı','Link copied'));}catch{showModal(t('Kopyala','Copy'),`<textarea readonly>${esc(text)}</textarea>`);}}
function issueBody(b){return `## ${t('Ortam','Environment')}\n${b.platform} · ${b.environment} · ${b.version}\n\n## ${t('Adımlar','Steps')}\n${b.steps.map((s,i)=>`${i+1}. ${s}`).join('\n')}\n\n## ${t('Beklenen','Expected')}\n${b.expected}\n\n## ${t('Gerçekleşen','Actual')}\n${b.actual}\n\n${t('Önem','Severity')}: ${name(b.severity)}\nForge ID: ${b.id}`;}
function importDialog(){showModal(t('CSV / Excel içe aktar','Import CSV / Excel'),`<form id="importForm" class="stack"><p>${t('İlk satırda title, steps ve expected başlıkları zorunludur. priority, platform, estimate ve preconditions isteğe bağlıdır. Excel’in ilk sayfası okunur.','The first row must contain title, steps and expected. priority, platform, estimate and preconditions are optional. The first Excel worksheet is read.')}</p>${field(t('Dosya (.csv / .xlsx, en fazla 5 MB)','File (.csv / .xlsx, maximum 5 MB)'),'<input type="file" name="file" accept=".csv,.xlsx" required>')}${button(t('Örnek CSV indir','Download sample CSV'),'csv-template')}<p class="note">${t('İçe alınan senaryolar taslak olur; onaylamadan plana eklenmez. Formüller çalıştırılmaz.','Imported scenarios remain drafts until approved. Formulas are not executed.')}</p><button type="submit" class="btn primary">${t('Dosyayı incele','Review file')}</button><div id="importReview"></div></form>`);}
async function uploadFile(file){if(file.size>5*1024*1024)throw Error(t('Dosya sınırı 5 MB.','File limit is 5 MB.'));let type=file.type;if(/\.(txt|log)$/i.test(file.name))type='text/plain';if(!['image/png','image/jpeg','image/webp','video/mp4','video/webm','text/plain'].includes(type))throw Error(t('Desteklenmeyen kanıt türü','Unsupported evidence type'));const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return api('/evidence',{name:file.name,type,data:btoa(binary)});}
async function start(){try{config=await api('/config');const share=new URLSearchParams(location.search).get('share');if(share){const data=await api('/shared/'+share);setTheme();root.innerHTML=`<main class="workspace"><div class="page-head"><div><div class="eyebrow">QAcrew Forge / ${t('Paylaşılan rapor','Shared report')}</div><h1>${esc(data.project)} · ${esc(data.version)}</h1><p>${t('Salt okunur anlık görüntü','Read-only snapshot')} · ${date(data.createdAt)} · ${t('Geçerlilik','Expires')}: ${date(data.expires)}</p></div>${button(t('Yazdır / PDF','Print / PDF'),'print')}</div>${reportBody(data)}</main>`;return;}try{const session=await api('/api/session');user=session.user;if(user.demo)user=null;}catch{}if(user){const data=await api('/members');members=data.members;user=data.user;await load();restoreLink();shell();const bug=new URLSearchParams(location.search).get('bug');if(bug)bugEditor(bug);}else login();}catch(e){root.innerHTML=`<main class="workspace"><h1>QAcrew Forge</h1><p class="error">${esc(e.message)}</p>${button(t('Yeniden dene','Retry'),'retry')}</main>`;}}
function restoreLink(){const params=new URLSearchParams(location.search);if(state.projects.some(p=>p.id===params.get('project')))projectId=params.get('project');if(params.get('bug'))tab='bugs';}
let importedScenarios=[];
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;try{
 if(action==='close-modal'){modal.close();return;}if(action==='theme'){theme=theme==='dark'?'light':'dark';setTheme();return;}if(action==='language'){language=language==='tr'?'en':'tr';modal.close();user?shell():login();return;}if(action==='retry'){await start();return;}
 if(action==='fill-login'){$('#loginForm [name=email]').value=b.dataset.email;$('#loginForm [name=password]').value='Preview-only-2026!';return;}
 if(action==='logout'){await fetch('/api/session',{method:'DELETE',credentials:'same-origin'});user=null;state=null;modal.close();login();return;}
 if(action==='nav'){tab=b.dataset.tab;activeRun='';shell();return;}if(action==='refresh'){await load();shell();return;}
 if(action==='toggle-projects'){if($('#projectMenu').hidden)openProjects();else closeProjects(true);return;}
 if(action==='choose-project'){projectId=id;version='';activeRun='';shell();$('#projectSelect').focus();return;}
 if(action==='new-project'){closeProjects();showModal(t('Yeni proje','New project'),`<form id="projectForm" class="stack">${field(t('Proje adı','Project name'),input('name','','required maxlength="200"'))}<button type="submit" class="btn primary">${t('Oluştur','Create')}</button></form>`);return;}
 if(action==='switch-project'){projectId=id;version='';activeRun='';tab='dashboard';shell();return;}
 if(action==='new-requirement'||action==='edit-requirement'){requirementEditor(id);return;}
 if(action==='scan-questions'){const input=$('#requirementForm [name=input]').value;if(!input.trim())throw Error(t('Önce gereksinimi yaz.','Enter a requirement first.'));$('#questionEditor').innerHTML=questionFields(questionList(input));return;}
 if(action==='github-import'){const number=$('#requirementForm [name=issue]').value;const data=await api('/github/issue?number='+encodeURIComponent(number));for(const k of ['title','input','source'])$('#requirementForm [name='+k+']').value=data[k];return;}
 if(action==='scenario-sub'){subtab=b.dataset.sub;renderContent();return;}
 if(action==='new-scenario'||action==='edit-scenario'){scenarioEditor(id);return;}
 if(action==='new-document'||action==='from-requirement'){documentCreator(action==='from-requirement'?id:'',b.dataset.type||'test');return;}
 if(action==='edit-document'){documentEditor(project().documents.find(d=>d.id===id));return;}
 if(action==='sample-input'){const f=$('#generateForm');f.elements.title.value=t('Oturum açma','Sign in');f.elements.input.value=t('Kayıtlı kullanıcı geçerli e-posta ve şifreyle giriş yapabilir.\nHatalı şifrede anlaşılır uyarı gösterilmelidir.\nBoş alanlar için doğrulama gösterilmelidir.','A registered user can sign in with a valid email and password.\nAn incorrect password must show a clear warning.\nEmpty fields must show validation.');$('#inputCount').textContent=f.elements.input.value.length+' / 12000';return;}
 if(action==='approve-document'){const doc=readDocument();if(!$('#documentForm').reportValidity())return;if(doc.rows.some(r=>!r.steps.trim()||!r.expected.trim()))throw Error(t('Her satırda adım ve beklenen sonuç gerekli.','Every row needs steps and an expected result.'));await command('document.save',doc);await command('scenario.import',{items:doc.rows.map(r=>({title:r.title,steps:r.steps.split('\n').filter(Boolean),expected:r.expected,priority:r.priority,platform:doc.platform,requirementId:doc.requirementId,estimate:5,approved:true}))});modal.close();tab='scenarios';subtab='library';shell();return;}
 if(action==='export-document'){const doc=readDocument();download(csv([['title','steps','expected','priority','platform'],...doc.rows.map(r=>[r.title,r.steps,r.expected,r.priority,doc.platform])]),'forge-document.csv','text/csv;charset=utf-8');return;}
 if(action==='import-scenarios'){importDialog();return;}if(action==='csv-template'){download(csv([['title','steps','expected','priority','platform','estimate'],['Sign in','Open login\nEnter valid credentials','Account page opens','High','Web',5]]),'forge-scenarios-template.csv','text/csv;charset=utf-8');return;}
 if(action==='confirm-import'){await command('scenario.import',{items:importedScenarios});modal.close();shell();return;}
 if(action==='export-scenarios'){download(csv([['title','steps','expected','priority','platform','estimate','preconditions'],...project().scenarios.map(s=>[s.title,s.steps.join('\n'),s.expected,s.priority,s.platform,s.estimate,s.preconditions])]),'forge-scenarios.csv','text/csv;charset=utf-8');return;}
 if(action==='new-plan'||action==='edit-plan'){planEditor(id);return;}
 if(action==='suggest-plan'){const form=$('#planForm'),notes=form.elements.notes.value.toLocaleLowerCase();if(!notes.trim())throw Error(t('Sürüm notunu yaz.','Enter release notes.'));form.querySelectorAll('[name=scenario]').forEach(c=>{const s=project().scenarios.find(s=>s.id===c.value);c.checked=s.title.toLocaleLowerCase().split(/[^\p{L}\p{N}]+/u).some(w=>w.length>3&&notes.includes(w));});planBudget();return;}
 if(action==='start-run'){await command('run.create',{planId:id});activeRun=project().runs.at(-1).id;tab='runs';shell();return;}
 if(action==='open-run'||action==='bug-run'){activeRun=id;tab='runs';runFilter='all';modal.close();shell();return;}if(action==='close-run'){activeRun='';renderContent();return;}
 if(action==='resume-run'){runFilter='pending';renderContent();$('.run-case')?.focus();$('.run-case')?.scrollIntoView({block:'center'});return;}
 if(action==='bulk-pass'){const ids=$$('[name=bulkCase]:checked').map(x=>x.value);if(!ids.length)throw Error(t('Önce bekleyen testleri seç.','Select pending tests first.'));showModal(t('Toplu sonuç onayı','Confirm bulk result'),`<p>${ids.length} ${t('test gerçekten yürütüldü ve geçti mi? Bu işlem yürütme geçmişine adınla kaydedilir.','tests have actually been executed and passed? This records your name in the execution history.')}</p>${button(t('Evet, seçilenleri geçti işaretle','Yes, mark selected as passed'),'confirm-bulk',`data-ids="${ids.join(',')}"`)}`);return;}
 if(action==='confirm-bulk'){await command('run.bulk',{runId:activeRun,caseIds:b.dataset.ids.split(',')});modal.close();renderContent();return;}
 if(action==='open-bug'){bugEditor(id);return;}if(action==='bug-link'){await copy(location.origin+location.pathname+'?project='+projectId+'&bug='+id);return;}
 if(action==='bug-csv'){const bug=project().bugs.find(x=>x.id===id);download(csv([['Summary','Description','Issue Type','Priority','Assignee','State'],[bug.title,issueBody(bug),'Bug',bug.severity,bug.assignee,bug.status]]),'forge-jira-azure-bug.csv','text/csv;charset=utf-8');return;}
 if(action==='github-export'){const bug=project().bugs.find(x=>x.id===id);showModal(t('GitHub aktarımını incele','Review GitHub export'),`<p>${esc(config.repository||t('Depo henüz yapılandırılmadı','Repository not configured'))}</p><h3>${esc(bug.title)}</h3><pre class="long">${esc(issueBody(bug))}</pre><p class="note">${config.github?t('Onayla düğmesi GitHub’da yeni bir issue açar.','Confirm creates a new GitHub issue.'):t('GitHub hesabında doldurulmuş bir issue taslağı açılır. Göndermeden önce orada kontrol edip onaylarsın.','A prefilled issue draft opens in your GitHub account. Review and submit it there.')}</p>${config.github?button(t('Onayla ve GitHub’a gönder','Confirm & send to GitHub'),'confirm-github',`data-id="${id}"`):`<a class="btn primary" target="_blank" rel="noopener" href="https://github.com/${esc(config.repository||'Smtrbci/qacrew-websites')}/issues/new?title=${encodeURIComponent(bug.title)}&body=${encodeURIComponent(issueBody(bug))}">${t('GitHub’da taslak aç','Open draft in GitHub')}</a>`}`);return;}
 if(action==='confirm-github'){b.disabled=true;try{const bug=project().bugs.find(x=>x.id===id),result=await api('/github/export',{title:bug.title,body:issueBody(bug)});showModal('GitHub',`<a href="${esc(result.url)}" target="_blank" rel="noopener">${esc(result.url)}</a>`);}finally{b.disabled=false;}return;}
 if(action==='evidence'){const file=await api('/evidence/'+id),bytes=Uint8Array.from(atob(file.data),c=>c.charCodeAt(0));download(bytes,file.name,file.type);return;}
 if(action==='print'){window.print();return;}if(action==='report-html'){const data=reportData();const css=await fetch('./workspace.css').then(r=>r.text());download(`<!doctype html><html lang="${language}"><meta charset="utf-8"><title>${esc(data.project)} ${esc(data.version)}</title><style>${css}</style><body><main class="workspace"><h1>${esc(data.project)} · ${esc(data.version)}</h1>${reportBody(data)}</main></body></html>`,'forge-release-report.html','text/html');return;}
 if(action==='share-report'){const data=reportData();if(!data.runs.length)throw Error(t('Koşum yok','No runs'));showModal(t('Raporu paylaş','Share report'),`<p>${t('Bağlantıya sahip herkes bu sürüm raporunun salt okunur kopyasını 7 gün boyunca görebilir. Notlar ve karar veren kişinin adı rapora dahildir; ham gereksinimler ve kanıt dosyaları paylaşılmaz.','Anyone with the link can read this release snapshot for 7 days. Notes and decision author are included; raw requirements and evidence files are not shared.')}</p>${button(t('Paylaşım bağlantısı oluştur','Create share link'),'confirm-share')}`);return;}
 if(action==='confirm-share'){const data=reportData(),result=await api('/share',{projectId,version:data.version}),link=location.origin+location.pathname+'?share='+result.token;showModal(t('Rapor bağlantısı','Report link'),`<p>${t('7 gün geçerli','Valid for 7 days')}</p><a class="long" href="${esc(link)}" target="_blank" rel="noopener">${esc(link)}</a>`);return;}
 if(action==='backup'){showModal(t('Yedek ve geri yükleme','Backup & restore'),`<div class="stack"><p>${t('JSON yedeği bütün projeleri, iş akışlarını ve kanıt dosyalarını içerir. Güvenli bir yerde sakla.','The JSON backup contains all projects, workflows and evidence. Store it securely.')}</p>${button(t('Tam yedeği indir','Download full backup'),'download-backup')}${can('pmo')?`<form id="restoreForm" class="stack"><p class="note">${t('Geri yükleme mevcut proje kayıtlarını değiştirir. Önce mevcut yedeği indir.','Restore replaces the current project records. Download a backup first.')}</p>${field('JSON','<input type="file" name="file" accept=".json" required>')}<label class="inline-field"><input name="confirm" type="checkbox" required>${t('Mevcut kayıtların değişeceğini anladım','I understand that current records will be replaced')}</label><button type="submit" class="btn danger">${t('Yedeği geri yükle','Restore backup')}</button></form>`:''}</div>`);return;}
 if(action==='download-backup'){b.disabled=true;try{const ids=[...new Set(state.projects.flatMap(p=>p.runs.flatMap(r=>r.cases.flatMap(c=>c.evidence||[]))))],evidence=[];for(const id of ids)evidence.push(await api('/evidence/'+id));download(JSON.stringify({...state,evidence},null,2),'forge-backup-'+new Date().toISOString().slice(0,10)+'.json','application/json');toast(t('Yedek indirildi','Backup downloaded'));}finally{b.disabled=false;}return;}
 }catch(error){toast(error.message);}});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!f.matches('form'))return;e.preventDefault();if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));const submit=f.querySelector('[type=submit]');if(submit)submit.disabled=true;
 try{
  if(f.id==='loginForm'){const result=await api('/api/session',{email:v.email,password:v.password});user=result.user;if(user.demo)throw Error(t('Bu ekran için önizleme veya gerçek ekip hesabını kullan.','Use a preview or real team account for this workspace.'));const data=await api('/members');members=data.members;user=data.user;await load();restoreLink();shell();const bug=new URLSearchParams(location.search).get('bug');if(bug)bugEditor(bug);}
  else if(f.id==='projectForm'){await command('project.create',{name:v.name});projectId=state.projects.at(-1).id;version='';modal.close();shell();}
  else if(f.id==='requirementForm'){await command('requirement.save',{id:f.dataset.id||undefined,title:v.title,input:v.input,source:v.source,questions:[...f.querySelectorAll('.question')].map(q=>({question:q.querySelector('[data-question]').textContent,answer:q.querySelector('[name=answer]').value,status:q.querySelector('[name=questionStatus]').value}))});modal.close();shell();}
  else if(f.id==='scenarioForm'){await command('scenario.save',{...v,id:f.dataset.id||undefined,steps:v.steps.split('\n').filter(Boolean),approved:f.elements.approved.checked});modal.close();shell();}
  else if(f.id==='documentForm'){await command('document.save',readDocument());modal.close();tab='scenarios';subtab='documents';shell();}
  else if(f.id==='generateForm'){
   if(!v.input.trim())throw Error(t('Girdi gerekli','Input required'));let rows,questions;const isEnglish=v.language==='en';
   if(config.ai){const r=await api('/api/generate',{job:{type:v.type,plats:[v.platform],depth:v.depth,project:project().name,input:v.input,language:v.language}}),result=r.result;
    if(v.type==='bug'){const b=result.bug;rows=[{title:b.title,steps:(b.steps||[]).join('\n')+'\n'+(b.actual||''),expected:b.expected,priority:b.severity||'Medium'}];questions=(b.missing_info||[]).map(question=>({question,answer:''}));}
    else{rows=(result.items||[]).map(x=>({title:x.scenario||x.check||x.scope,steps:(x.steps||[]).join('\n')||x.note||x.reason||'',expected:x.expected||x.check||x.scope||'',priority:x.priority||'Medium'}));questions=(result.questions||[]).map(question=>({question,answer:''}));}
   }else{
    const source=v.input.split(/\n+/).map(x=>x.replace(/^[-•]\s*/, '').trim()).filter(Boolean).slice(0,v.depth==='deep'?14:6);
    rows=source.map((line,index)=>({title:`${v.platform} · ${({'test':isEnglish?'Verify':'Doğrula','bug':isEnglish?'Investigate':'İncele','smoke':isEnglish?'Quick check':'Hızlı kontrol','reg':isEnglish?'Regression':'Regresyon'})[v.type]} ${index+1}: ${line.slice(0,150)}`,steps:(isEnglish?'Review the source requirement and perform the described action: ':'Kaynak gereksinimi gözden geçir ve belirtilen işlemi uygula: ')+line,expected:v.type==='bug'?(isEnglish?'Expected vs actual behavior must be confirmed; no observed bug is asserted.':'Beklenen ve gerçekleşen davranış doğrulanmalıdır; gözlenmiş bir hata iddia edilmez.'):line,priority:'Medium'}));
    const old=language;language=v.language;questions=questionList(v.input);language=old;
   }
   const req=project().requirements.find(r=>r.id===v.requirementId);if(req)questions=req.questions.map(q=>({question:q.question,answer:q.answer}));
   const normalize={'Yüksek':'High','Orta':'Medium','Düşük':'Low','Kritik':'Critical'};rows=rows.map(r=>({...r,priority:normalize[r.priority]||r.priority}));
   documentEditor({title:v.title,type:v.type,platform:v.platform,language:v.language,requirementId:v.requirementId,rows,questions,sample:!config.ai});
  }
  else if(f.id==='planForm'){const scenarioIds=[...f.querySelectorAll('[name=scenario]:checked')].map(c=>c.value),assignments={};for(const sid of scenarioIds)assignments[sid]=f.elements['assignee-'+sid].value;await command('plan.save',{...v,id:f.dataset.id||undefined,scenarioIds,assignments});modal.close();tab='plans';shell();}
  else if(f.matches('.resultForm')){
   if(['failed','blocked'].includes(v.status)&&v.note.trim().length<10)throw Error(t('Kaldı/Engellendi için en az 10 karakter not yaz.','Write at least 10 characters for Failed/Blocked.'));
   const evidence=[];for(const file of f.elements.evidence.files)evidence.push((await uploadFile(file)).id);
   await command('run.result',{runId:f.dataset.run,caseId:f.dataset.case,status:v.status,note:v.note,evidence,bug:v.status==='failed'?{title:v.bugTitle,severity:v.severity,assignee:v.assignee}:undefined});
   const caseId=f.dataset.case;renderContent();$('#case-'+caseId)?.focus();
  }
  else if(f.id==='bugForm'){await command('bug.update',{...v,id:f.dataset.id});bugEditor(f.dataset.id);renderContent();}
  else if(f.id==='retestForm'){await command('retest.save',{id:f.dataset.id,note:v.note,passed:v.passed==='true'});bugEditor(f.dataset.id);renderContent();}
  else if(f.id==='decisionForm'){await command('decision.save',{...v,version:reportData().version});renderContent();}
  else if(f.id==='importForm'){const file=f.elements.file.files[0];if(file.size>5*1024*1024)throw Error('5 MB limit');const rows=file.name.toLowerCase().endsWith('.xlsx')?await parseXLSX(file):parseCSV(await file.text());importedScenarios=scenariosFromRows(rows);if(!importedScenarios.length||importedScenarios.length>1000)throw Error('1–1000 scenarios');$('#importReview').innerHTML=`<p>${importedScenarios.length} ${t('senaryo bulundu. İlk 5 satır:','scenarios found. First 5 rows:')}</p><ul>${importedScenarios.slice(0,5).map(s=>`<li>${esc(s.title)} · ${esc(s.platform)}</li>`).join('')}</ul>${button(t('Onayla ve içe aktar','Confirm import'),'confirm-import')}`;}
  else if(f.id==='restoreForm'){
   const file=f.elements.file.files[0];if(file.size>75000000)throw Error('75 MB limit');const data=JSON.parse(await file.text());if(data.schema!==1||!Array.isArray(data.projects))throw Error(t('Geçersiz yedek','Invalid backup'));const mapping={};for(const evidence of data.evidence||[]){const result=await api('/evidence',evidence);mapping[evidence.id]=result.id;}for(const p of data.projects){for(const r of p.runs)for(const c of r.cases)c.evidence=(c.evidence||[]).map(id=>mapping[id]||id);for(const b of p.bugs)b.evidence=(b.evidence||[]).map(id=>mapping[id]||id);}delete data.evidence;await command('restore.import',{data});modal.close();await load();shell();
  }
 }catch(error){const box=f.querySelector('[role=alert]')||f.querySelector('.error');if(box){box.textContent=error.message;box.hidden=false;box.scrollIntoView({block:'nearest'});}else toast(error.message);}finally{if(submit)submit.disabled=false;}
});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='projectSelect'){projectId=el.value;version='';activeRun='';shell();}else if(el.id==='versionSelect'){version=el.value;activeRun='';renderContent();}else if(el.id==='docType'){docType=el.value;renderContent();}else if(el.id==='docSort'){docSort=el.value;renderContent();}else if(el.id==='runFilter'){runFilter=el.value;renderContent();}else if(el.id==='bugFilter'){bugFilter=el.value;renderContent();}else if(el.name==='status'&&el.closest('.resultForm')){el.closest('form').querySelector('.bug-inline').hidden=el.value!=='failed';}else if(el.closest('#planForm'))planBudget();else if(el.name==='requirementId'&&el.closest('#generateForm')){const r=project().requirements.find(x=>x.id===el.value);if(r){el.form.elements.title.value=r.title;el.form.elements.input.value=r.input;$('#inputCount').textContent=r.input.length+' / 12000';}}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='docSearch'){const start=el.selectionStart;docQuery=el.value;renderContent();$('#docSearch').focus();$('#docSearch').setSelectionRange(start,start);}if(el.name==='note'&&el.closest('.resultForm'))el.closest('form').querySelector('.counter').textContent=el.value.length+' '+t('karakter · en az 10 (Kaldı / Engellendi)','characters · minimum 10 (Failed / Blocked)');if(el.name==='input'&&el.closest('#generateForm'))$('#inputCount').textContent=el.value.length+' / 12000';if(el.closest('#planForm'))planBudget();});
document.addEventListener('keydown',e=>{if(!e.altKey||tab!=='runs'||!activeRun||modal.open)return;const card=document.activeElement.closest('.run-case')||$('.run-case'),form=card?.querySelector('form');if(!form)return;const key=e.key.toLowerCase();if(!['p','f','b','n'].includes(key))return;e.preventDefault();if(key==='n'){const cards=$$('.run-case'),next=cards[cards.indexOf(card)+1]||cards[0];next?.focus();next?.scrollIntoView({block:'center'});return;}form.elements.status.value=key==='p'?'passed':key==='f'?'failed':'blocked';form.querySelector('.bug-inline').hidden=key!=='f';if(key==='p')form.requestSubmit();else form.elements.note.focus();});
await start();

document.addEventListener('invalid',e=>{const form=e.target.closest('form'),box=form?.querySelector('.error');if(box){box.textContent=t('Lütfen zorunlu alanları doldurun ve seçimleri kontrol edin.','Fill the required fields and check your selections.');box.hidden=false;}},true);
